        "**Presyncope** is the feeling of being about to faint - greying of vision, sweating and a need to sit down",
        "Presyncope means a transient fall in cerebral perfusion",
        "Causes of presyncope: postural hypotension, arrhythmia, anaemia, hypoglycaemia, dehydration, drugs",
        "**Disequilibrium** is unsteadiness felt in the legs only on standing or walking, with no illusion of movement",
        "Disequilibrium means a problem with the sensory or motor apparatus of balance",
        "Causes of disequilibrium: peripheral neuropathy, cerebellar disease, parkinsonism, poor vision, multiple deficits in the elderly",
