        "Do not ask what does it feel like - patients answer inconsistently and change their answer within minutes [TiTrATE 2015]",
        "Ask instead: when did it start, how long does each episode last, what brings it on, and what else happens with it",
        "This is the **TiTrATE** approach - Timing, Triggers, And Targeted Examination [TiTrATE 2015]",
