        "Chronic cough is airway disease, reflux or drugs [CHEST 2018]",
        "India overrides this with a **two-week rule** under the National Tuberculosis Elimination Programme [NTEP 2020]",
        "A cough of two weeks or more defines presumptive pulmonary tuberculosis and mandates a sputum test [NTEP 2020]",
        "Fever of two weeks, significant weight loss, or haemoptysis of any duration also define presumptive tuberculosis [NTEP 2020]",
        "Any abnormality on a chest radiograph defines presumptive tuberculosis [NTEP 2020]",
        "India carries about **a quarter** of the world's tuberculosis, with an estimated 2.8 million cases a year [WHO 2024]",
        "In a person living with HIV or a household contact of a tuberculosis patient, a cough of **any duration** is presumptive tuberculosis [NTEP 2020]",
        "In diabetes, silicosis or immunosuppression a cough of any duration is presumptive tuberculosis - the testing threshold is lower still",
