        "Ask about diabetes, HIV risk, alcohol, tobacco, silica exposure, and time spent in a prison, a hostel or a slum",
        "Characterise the cough - dry or productive, the colour and quantity of sputum, blood",
        "Nocturnal and early-morning cough suggests **asthma**",
        "Cough after meals and on lying suggests reflux",
        "Cough on waking with sputum suggests bronchiectasis or COPD",
